import{_ as n,o as a,c as s,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"68. Environment Variables","description":"The Little Book of C — 68. Environment Variables","frontmatter":{"title":"68. Environment Variables","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working Close to the System"],"description":"The Little Book of C — 68. Environment Variables","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":68,"sidebarWeight":68,"lang":"en-US","alternateEn":"/posts/c教程/en-US/07-Working Close to the System/068-Environment Variables","alternateZh":"/posts/c教程/zh-CN/07-贴近系统/068-Environment Variables"},"headers":[],"relativePath":"posts/c教程/en-US/07-Working Close to the System/068-Environment Variables.md","filePath":"posts/c教程/en-US/07-Working Close to the System/068-Environment Variables.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/07-Working Close to the System/068-Environment Variables.md"};function p(o,e,l,r,c,d){return a(),s("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/07-贴近系统/068-Environment Variables)</p><p>Every program in Unix inherits a set of key–value pairs called environment variables. They store information about your shell, system configuration, and runtime behavior, such as your username, home directory, and compiler paths.</p><p>C gives you full control to read, modify, and define these variables directly.</p><h4 id="step-1-what-are-environment-variables" tabindex="-1">Step 1. What Are Environment Variables? <a class="header-anchor" href="#step-1-what-are-environment-variables" aria-label="Permalink to &quot;Step 1. What Are Environment Variables?&quot;">​</a></h4><p>Environment variables are strings of the form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KEY=VALUE</span></span></code></pre></div><p>You can view them in your shell:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printenv</span></span></code></pre></div><p>Common examples:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HOME=/home/user</span></span>
<span class="line"><span>PATH=/usr/local/bin:/usr/bin:/bin</span></span>
<span class="line"><span>USER=alice</span></span>
<span class="line"><span>LANG=en_US.UTF-8</span></span>
<span class="line"><span>SHELL=/bin/bash</span></span></code></pre></div><p>These values are passed to every program when you run it.</p><h4 id="step-2-accessing-environment-variables-in-c" tabindex="-1">Step 2. Accessing Environment Variables in C <a class="header-anchor" href="#step-2-accessing-environment-variables-in-c" aria-label="Permalink to &quot;Step 2. Accessing Environment Variables in C&quot;">​</a></h4><p>You can use the standard library function<code>getenv()</code> to read a variable.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    const char *path = getenv(&quot;PATH&quot;);</span></span>
<span class="line"><span>    if (path)</span></span>
<span class="line"><span>        printf(&quot;PATH = %s\\n&quot;, path);</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        printf(&quot;PATH not found.\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATH = /usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin</span></span></code></pre></div><p>If the variable doesn’t exist,<code>getenv()</code> returns<code>NULL</code>.</p><h4 id="step-3-setting-environment-variables" tabindex="-1">Step 3. Setting Environment Variables <a class="header-anchor" href="#step-3-setting-environment-variables" aria-label="Permalink to &quot;Step 3. Setting Environment Variables&quot;">​</a></h4><p>To define or change a variable inside your program, use<code>setenv()</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    setenv(&quot;GREETING&quot;, &quot;Hello from C!&quot;, 1);</span></span>
<span class="line"><span>    printf(&quot;%s\\n&quot;, getenv(&quot;GREETING&quot;));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>setenv(name, value, overwrite)</code></p><ul><li><code>overwrite = 0</code>: don’t overwrite existing variable.</li><li><code>overwrite = 1</code>: replace it if it exists.</li></ul><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello from C!</span></span></code></pre></div><h4 id="step-4-removing-environment-variables" tabindex="-1">Step 4. Removing Environment Variables <a class="header-anchor" href="#step-4-removing-environment-variables" aria-label="Permalink to &quot;Step 4. Removing Environment Variables&quot;">​</a></h4><p>Use<code>unsetenv()</code> to delete a variable.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    setenv(&quot;TEMPVAR&quot;, &quot;temporary&quot;, 1);</span></span>
<span class="line"><span>    printf(&quot;Before unset: %s\\n&quot;, getenv(&quot;TEMPVAR&quot;));</span></span>
<span class="line"><span>    unsetenv(&quot;TEMPVAR&quot;);</span></span>
<span class="line"><span>    printf(&quot;After unset: %s\\n&quot;, getenv(&quot;TEMPVAR&quot;));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Before unset: temporary</span></span>
<span class="line"><span>After unset: (null)</span></span></code></pre></div><h4 id="step-5-accessing-all-environment-variables" tabindex="-1">Step 5. Accessing All Environment Variables <a class="header-anchor" href="#step-5-accessing-all-environment-variables" aria-label="Permalink to &quot;Step 5. Accessing All Environment Variables&quot;">​</a></h4><p>The<code>environ</code> global variable gives you access to the entire environment list.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>extern char **environ;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    for (char **env = environ; *env != NULL; env++) {</span></span>
<span class="line"><span>        printf(&quot;%s\\n&quot;, *env);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This prints all environment variables currently active in your process.</p><h4 id="step-6-passing-environment-variables-to-child-processes" tabindex="-1">Step 6. Passing Environment Variables to Child Processes <a class="header-anchor" href="#step-6-passing-environment-variables-to-child-processes" aria-label="Permalink to &quot;Step 6. Passing Environment Variables to Child Processes&quot;">​</a></h4><p>When you use<code>fork()</code> and<code>exec()</code>, environment variables are inherited by the child process automatically.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    setenv(&quot;HELLO&quot;, &quot;world&quot;, 1);</span></span>
<span class="line"><span>    execlp(&quot;printenv&quot;, &quot;printenv&quot;, &quot;HELLO&quot;, NULL);</span></span>
<span class="line"><span>    perror(&quot;execlp&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>world</span></span></code></pre></div><p>You can also provide a custom environment list using<code>execle()</code> or<code>execve()</code>.</p><h4 id="step-7-custom-environment-for-a-new-program" tabindex="-1">Step 7. Custom Environment for a New Program <a class="header-anchor" href="#step-7-custom-environment-for-a-new-program" aria-label="Permalink to &quot;Step 7. Custom Environment for a New Program&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char *newenv[] = { &quot;MODE=debug&quot;, &quot;VERSION=1.0&quot;, NULL };</span></span>
<span class="line"><span>    execle(&quot;/usr/bin/env&quot;, &quot;env&quot;, NULL, newenv);</span></span>
<span class="line"><span>    perror(&quot;execle&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MODE=debug</span></span>
<span class="line"><span>VERSION=1.0</span></span></code></pre></div><p>Only these two variables exist for the new process, everything else is discarded.</p><h4 id="step-8-why-environment-variables-matter" tabindex="-1">Step 8. Why Environment Variables Matter <a class="header-anchor" href="#step-8-why-environment-variables-matter" aria-label="Permalink to &quot;Step 8. Why Environment Variables Matter&quot;">​</a></h4><p>They are a key part of Unix’s design philosophy:</p><ul><li>Programs should be configurable without recompilation.</li><li>Environment variables provide global, process-level configuration.</li></ul><p>For example:</p><ul><li><code>PATH</code> controls where executables are searched.</li><li><code>HOME</code> defines user directories.</li><li><code>LANG</code> defines locale settings.</li><li><code>LD_LIBRARY_PATH</code> controls dynamic linking.</li></ul><h4 id="step-9-security-considerations" tabindex="-1">Step 9. Security Considerations <a class="header-anchor" href="#step-9-security-considerations" aria-label="Permalink to &quot;Step 9. Security Considerations&quot;">​</a></h4><p>Environment variables are inherited automatically, so they can be a security risk if not handled carefully:</p><ul><li>Avoid trusting environment variables for authentication.</li><li>Always validate<code>PATH</code>,<code>HOME</code>, and<code>TMPDIR</code>.</li><li>Use<code>unsetenv()</code> for sensitive contexts (e.g., setuid programs).</li></ul><h4 id="tiny-code-mini-shell-with-path-lookup" tabindex="-1">Tiny Code: Mini Shell with PATH Lookup <a class="header-anchor" href="#tiny-code-mini-shell-with-path-lookup" aria-label="Permalink to &quot;Tiny Code: Mini Shell with PATH Lookup&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    const char *path = getenv(&quot;PATH&quot;);</span></span>
<span class="line"><span>    if (!path) path = &quot;(none)&quot;;</span></span>
<span class="line"><span>    printf(&quot;Current PATH:\\n%s\\n&quot;, path);</span></span>
<span class="line"><span>    setenv(&quot;PATH&quot;, &quot;/usr/local/bin:/usr/bin&quot;, 1);</span></span>
<span class="line"><span>    printf(&quot;\\nUpdated PATH:\\n%s\\n&quot;, getenv(&quot;PATH&quot;));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Current PATH:</span></span>
<span class="line"><span>/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Updated PATH:</span></span>
<span class="line"><span>/usr/local/bin:/usr/bin</span></span></code></pre></div><h4 id="step-10-why-it-matters" tabindex="-1">Step 10. Why It Matters <a class="header-anchor" href="#step-10-why-it-matters" aria-label="Permalink to &quot;Step 10. Why It Matters&quot;">​</a></h4><p>Environment variables give your programs context:</p><ul><li>They tell you where files, libraries, and configs live.</li><li>They let you control runtime behavior dynamically.</li><li>They’re essential for system tools, shells, daemons, and tests.</li></ul><p>Understanding how to read and modify them is key to mastering Unix programming in C.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Print all environment variables sorted alphabetically.</li><li>Implement your own<code>env</code> command in C.</li><li>Write a program that modifies<code>PATH</code> and launches another program.</li><li>Create a child process that inherits modified variables.</li><li>Combine<code>setenv()</code>,<code>execle()</code>, and<code>getenv()</code> to simulate sandboxed runs.</li></ol><p>Next, you’ll learn about error handling and return codes, the invisible signals that every Unix process uses to tell the system whether it succeeded or failed.</p>`,63)])])}const v=n(i,[["render",p]]);export{h as __pageData,v as default};
